// Generated by OpenAI Codex on 2026-11-03. Database map editor with selected-only geometry tools.
import L from 'leaflet';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { MapContainer, Marker, Polyline, TileLayer, useMap, useMapEvents } from 'react-leaflet';
import { MapDocument, type Position, type Tags } from '../mapDocument';
import BuildingAutocomplete from './BuildingAutocomplete';

const api = process.env.EXPO_PUBLIC_API_URL || 'http://localhost:8000/api';
type Mode = 'select' | 'point' | 'building' | 'parking' | 'area';
type Action = (model: MapDocument) => string | void;
const icon = (text: string, color: string) =>
  L.divIcon({
    className: '',
    html: `<span style="display:grid;place-items:center;width:24px;height:24px;background:${color};color:white;border:2px solid white;border-radius:50%;box-shadow:0 1px 4px #222;font:bold 14px sans-serif">${text}</span>`,
    iconSize: [24, 24],
    iconAnchor: [12, 12],
  });
const vertexIcon = icon('●', '#1565c0');
const sharedIcon = icon('●', '#a33131');
const midpointIcon = icon('+', '#327046');
const entranceIcon = icon('E', '#7d3b9c');

function Features({
  model,
  selected,
  select,
  mode,
}: {
  model: MapDocument;
  selected: string;
  select: (id: string) => void;
  mode: Mode;
}) {
  const map = useMap();
  const fitted = useRef(false);
  useEffect(() => {
    const layer = L.geoJSON(model.geoJSON(), {
      style: (feature) => ({
        color: feature?.id === selected ? '#e36914' : '#2779a7',
        weight: feature?.id === selected ? 5 : 2,
      }),
      pointToLayer: (_feature, latlng) => L.circleMarker(latlng, { radius: 6 }),
      onEachFeature(feature, item) {
        const key = String(feature.id);
        const tags = feature.properties?.tags ?? feature.properties ?? {};
        const label = document.createElement('span');
        label.textContent = tags.name || tags['name:en'] || key;
        item.bindTooltip(label);
        item.on('click', (event) => {
          if (mode === 'select') {
            L.DomEvent.stopPropagation(event.originalEvent);
            select(key);
          }
        });
      },
    }).addTo(map);
    if (!fitted.current && layer.getBounds().isValid()) {
      map.fitBounds(layer.getBounds());
      fitted.current = true;
    }
    return () => {
      map.removeLayer(layer);
    };
  }, [map, model, selected, select, mode]);
  return null;
}
function Clicks({ click }: { click: (p: Position) => void }) {
  useMapEvents({ click: (event) => click([event.latlng.lat, event.latlng.lng]) });
  return null;
}
function Focus({ model, selected }: { model: MapDocument; selected: string }) {
  const map = useMap();
  const focused = useRef('');
  useEffect(() => {
    if (!selected) {
      focused.current = '';
      return;
    }
    if (focused.current === selected) return;
    focused.current = selected;
    try {
      const refs = selected.startsWith('node/') ? [selected] : model.refs(selected);
      const points = refs.map((ref) => model.position(ref));
      if (points.length) map.fitBounds(L.latLngBounds(points).pad(0.3), { maxZoom: 19 });
    } catch {
      /* Incomplete source ways remain inspectable through their tags. */
    }
  }, [map, selected, model]);
  return null;
}

export default function OsmEditor() {
  const [draft, setDraft] = useState('');
  const [saved, setSaved] = useState('');
  const [revision, setRevision] = useState(0);
  const [selected, setSelected] = useState('');
  const [tagDraft, setTagDraft] = useState<Tags | null>(null);
  const setTags = setTagDraft;
  const [undo, setUndo] = useState<string[]>([]);
  const [redo, setRedo] = useState<string[]>([]);
  const [message, setMessage] = useState('Loading local dataset…');
  const [busy, setBusy] = useState(false);
  const [mode, setMode] = useState<Mode>('select');
  const [points, setPoints] = useState<Position[]>([]);
  const [vertex, setVertex] = useState<number | null>(null);
  const [entrances, setEntrances] = useState(false);
  const [tiles, setTiles] = useState(true);
  const [query, setQuery] = useState('');
  const model = useMemo(() => (draft ? new MapDocument(draft) : null), [draft]);
  const originalTags = useMemo(
    () => (model?.objects.has(selected) ? model.tags(selected) : []),
    [model, selected],
  );
  const tags = tagDraft ?? originalTags;
  const pendingTags = JSON.stringify(tags) !== JSON.stringify(originalTags);
  const dirty = draft !== saved || pendingTags || points.length > 0;

  useEffect(() => {
    const handler = (event: BeforeUnloadEvent) => {
      if (dirty) {
        event.preventDefault();
        event.returnValue = '';
      }
    };
    window.addEventListener('beforeunload', handler);
    return () => window.removeEventListener('beforeunload', handler);
  }, [dirty]);
  useEffect(() => {
    let active = true;
    fetch(`${api}/map/editor`, { cache: 'no-store', credentials: 'include' })
      .then(async (response) => {
        if (!response.ok)
          throw new Error(
            'Editing is restricted to approved developers. Sign in with an authorized account.',
          );
        const data = await response.json();
        if (active) {
          setDraft(JSON.stringify(data.objects));
          setSaved(JSON.stringify(data.objects));
          setRevision(data.revision);
          setMessage(
            'Select an object or search by name / source OSM ID. Changes stay in your draft until Save.',
          );
        }
      })
      .catch((error) => {
        if (active) setMessage(error.message);
      });
    return () => {
      active = false;
    };
  }, []);

  const select = useCallback(
    (key: string) => {
      if (pendingTags && !window.confirm('Discard unapplied tag edits?')) return;
      setTagDraft(null);
      setSelected(key);
      setVertex(null);
      setMode('select');
    },
    [pendingTags],
  );
  function edit(action: Action) {
    if (!model || busy) return;
    try {
      const next = new MapDocument(draft);
      const selection = action(next);
      setUndo((previous) => [...previous.slice(-9), draft]);
      setRedo([]);
      setDraft(next.serialize());
      setTagDraft(null);
      setVertex(null);
      if (selection) setSelected(selection);
      setMessage('Draft updated. Save when ready.');
    } catch (error) {
      setMessage(String(error));
    }
  }
  function start(next: Mode) {
    if (pendingTags) {
      setMessage('Apply or reset tag edits first.');
      return;
    }
    setMode(next);
    setPoints([]);
    setVertex(null);
  }
  function click(position: Position) {
    if (mode === 'point') {
      edit((next) => next.node(position, [['name', 'New point']]));
      setMode('select');
    } else if (mode !== 'select') setPoints((previous) => [...previous, position]);
  }
  function finish() {
    const defaults: Tags =
      mode === 'building'
        ? [['building', 'yes']]
        : mode === 'parking'
          ? [['amenity', 'parking']]
          : [['area', 'yes']];
    edit((next) => next.polygon(points, defaults));
    setPoints([]);
    setMode('select');
  }
  async function save() {
    setBusy(true);
    try {
      const response = await fetch(`${api}/map/editor`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...new MapDocument(draft).changesSince(saved), revision }),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.detail || 'Save failed');
      const freshResponse = await fetch(`${api}/map/editor`, {
        credentials: 'include',
        cache: 'no-store',
      });
      if (!freshResponse.ok) {
        setMessage('Saved, but refresh failed. Reload before editing again.');
        return;
      }
      const fresh = await freshResponse.json();
      const serialized = JSON.stringify(fresh.objects);
      setDraft(serialized);
      setSaved(serialized);
      window.dispatchEvent(new Event('cats-map-updated'));
      setRevision(fresh.revision);
      setUndo([]);
      setRedo([]);
      setMessage(
        `Saved database revision ${data.revision}. All changes are recorded in the audit history.`,
      );
    } catch (error) {
      setMessage(String(error));
    } finally {
      setBusy(false);
    }
  }
  function exportDraft() {
    const url = URL.createObjectURL(new Blob([draft], { type: 'application/json' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = 'campus-draft.json';
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  const results = useMemo(() => {
    if (!model || !query.trim()) return [];
    const search = query.toLowerCase();
    return Array.from(model.objects.keys())
      .filter(
        (key) =>
          (search === 'needs review' &&
            ['unlinked', 'ambiguous', 'unlinked_manual'].includes(
              model.object(key).link_status || '',
            )) ||
          key.includes(search) ||
          String(model.object(key).osm_id ?? '').includes(search) ||
          model
            .tags(key)
            .some(
              ([k, v]) =>
                [
                  'name',
                  'alt_name',
                  'short_name',
                  'official_name',
                  'old_name',
                  'ref',
                  'amenity',
                  'building',
                ].includes(k) && v.toLowerCase().includes(search),
            ),
      )
      .slice(0, 50);
  }, [model, query]);
  const refs = model && selected.startsWith('way/') ? model.refs(selected) : [];
  const closed = refs.length > 1 && refs[0] === refs[refs.length - 1];
  const vertices = closed ? refs.slice(0, -1) : refs;
  const vertexKey = vertex !== null ? vertices[vertex] : undefined;
  const shared = model && refs.some((ref) => model.users(ref).some((key) => key !== selected));
  const members =
    model?.objects.get(selected)?.type === 'relation' ? model.object(selected).refs : [];
  const validSelection = model?.objects.has(selected);

  return (
    <div className="osm-editor">
      <style>{`
      .osm-editor {display:flex; flex:1; min-height:75vh; padding-top:80px; box-sizing:border-box; color:#172b3a; background:#f6f8fa; font:14px system-ui;}
      .osm-editor aside {width:340px; flex-shrink:0; max-height:calc(100vh - 80px); overflow:auto; padding:16px; box-sizing:border-box;}
      .osm-editor button,.osm-editor input,.osm-editor select {font:inherit; padding:7px; margin:3px 2px; border:1px solid #aeb9c4; border-radius:5px;}
      .osm-editor button {background:white; cursor:pointer;} .osm-editor button:disabled {opacity:.45;cursor:default;}
      .osm-editor input {min-width:0;box-sizing:border-box;} .osm-editor .tag {display:flex;} .osm-editor .tag input {width:43%;}
      .osm-editor h3 {overflow-wrap:anywhere;} .osm-editor .notice {background:#e4edf5;padding:10px;overflow-wrap:anywhere;} .osm-editor fieldset {border:0;padding:0;min-width:0;}
      .osm-editor .canvas {flex:1;min-width:0;min-height:70vh;} .osm-editor .primary {background:#155d9b;color:white;}
      @media(max-width:700px){.osm-editor {flex-direction:column}.osm-editor aside {width:100%;max-height:40vh}.osm-editor .canvas {height:60vh;flex:auto;min-height:60vh}}
    `}</style>
      <aside>
        <h2>Campus map editor</h2>
        <p>Database map · {dirty ? 'Unsaved changes' : 'No unsaved changes'}</p>
        <p role="status" className="notice">
          {message}
        </p>
        {model && (
          <fieldset disabled={busy}>
            <button
              className="primary"
              disabled={draft === saved || pendingTags || points.length > 0}
              onClick={() => void save()}
            >
              {busy ? 'Saving…' : 'Save to database'}
            </button>
            <button
              disabled={!undo.length || pendingTags}
              onClick={() => {
                setRedo((previous) => [...previous, draft]);
                setDraft(undo[undo.length - 1]);
                setUndo(undo.slice(0, -1));
                setSelected('');
                setTagDraft(null);
              }}
            >
              Undo
            </button>
            <button
              disabled={!redo.length || pendingTags}
              onClick={() => {
                setUndo((previous) => [...previous, draft]);
                setDraft(redo[redo.length - 1]);
                setRedo(redo.slice(0, -1));
                setSelected('');
                setTagDraft(null);
              }}
            >
              Redo
            </button>
            <button disabled={pendingTags || !!points.length} onClick={exportDraft}>
              Export draft
            </button>
            <button
              onClick={() => {
                if (window.confirm('Discard your draft and reload the map from the database?'))
                  window.location.reload();
              }}
            >
              Discard / reload
            </button>
            <p>
              Changes are audited in the database. Undo retains the last 10 draft edits and resets
              after saving.
            </p>
            <label>
              <input
                type="checkbox"
                checked={tiles}
                onChange={(event) => setTiles(event.target.checked)}
              />{' '}
              Show background tiles
            </label>
            <p>Background tiles are not editable. Turn them off to see only database features.</p>
            <h3>Find an object</h3>
            <button onClick={() => setQuery('needs review')}>
              Review unlinked entrances (
              {
                Array.from(model.objects.values()).filter((obj) =>
                  ['unlinked', 'ambiguous', 'unlinked_manual'].includes(obj.link_status || ''),
                ).length
              }
              )
            </button>
            <input
              aria-label="Search objects"
              placeholder="Name, type, or way/123…"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              style={{ width: '100%' }}
            />
            {results.length > 0 && (
              <select
                aria-label="Search results"
                size={Math.min(6, results.length + 1)}
                value={selected}
                onChange={(event) => select(event.target.value)}
                style={{ width: '100%' }}
              >
                <option value="" disabled>
                  Select a result (first 50)
                </option>
                {results.map((key) => (
                  <option key={key} value={key}>
                    {model.tags(key).find(([k]) => k === 'name')?.[1] || key} · {key}
                  </option>
                ))}
              </select>
            )}
            <h3>Create</h3>
            <button onClick={() => start('point')}>Point</button>
            <button onClick={() => start('building')}>Building</button>
            <button onClick={() => start('parking')}>Parking lot</button>
            <button onClick={() => start('area')}>Other area</button>
            {mode !== 'select' && (
              <div className="notice">
                <p>
                  {mode === 'point'
                    ? 'Click the map to place a point.'
                    : `Click each corner of the ${mode}. ${points.length} vertices placed.`}
                </p>
                {mode !== 'point' && (
                  <>
                    <button disabled={points.length < 3} onClick={finish}>
                      Finish boundary
                    </button>
                    <button
                      disabled={!points.length}
                      onClick={() => setPoints(points.slice(0, -1))}
                    >
                      Undo last corner
                    </button>
                  </>
                )}
                <button onClick={() => start('select')}>Cancel drawing</button>
              </div>
            )}
            {validSelection && (
              <>
                <h3>Selected: {selected}</h3>
                <button
                  onClick={() => {
                    if (window.confirm(`Delete ${selected} from your local dataset?`))
                      edit((next) => {
                        next.delete(selected);
                        setSelected('');
                        setTagDraft(null);
                      });
                  }}
                >
                  Delete object
                </button>
                {model.users(selected).length > 0 && (
                  <div>
                    <p>Referenced by (select to edit its boundary or relation):</p>
                    {model.users(selected).map((key) => (
                      <button key={key} onClick={() => select(key)}>
                        {key}
                      </button>
                    ))}
                  </div>
                )}
                {selected.startsWith('node/') &&
                  model.object(selected).tags.entrance &&
                  model.object(selected).tags.entrance !== 'no' && (
                    <div>
                      <h4>Entrance building</h4>
                      <p>
                        Link status: {model.object(selected).link_status || 'pending save'}. Choose
                        a stable building ID; names may change.
                      </p>
                      <BuildingAutocomplete
                        key={`${selected}:${model.object(selected).building_id || ''}`}
                        buildings={Array.from(model.objects.values()).filter(
                          (obj) =>
                            obj.type !== 'node' && obj.tags.building && obj.tags.building !== 'no',
                        )}
                        value={model.object(selected).building_id}
                        disabled={pendingTags}
                        onSelect={(id) => edit((next) => next.linkBuilding(selected, id))}
                      />
                    </div>
                  )}
                <h4>Tags</h4>
                <p>Edit any tag name or value. Apply before switching objects or saving.</p>
                {tags.map(([key, value], i) => (
                  <div className="tag" key={i}>
                    <input
                      aria-label={`Tag ${i + 1} key`}
                      value={key}
                      onChange={(event) =>
                        setTags(
                          tags.map((tag, n) => (n === i ? [event.target.value, tag[1]] : tag)),
                        )
                      }
                    />
                    <input
                      aria-label={`Tag ${i + 1} value`}
                      value={value}
                      onChange={(event) =>
                        setTags(
                          tags.map((tag, n) => (n === i ? [tag[0], event.target.value] : tag)),
                        )
                      }
                    />
                    <button
                      aria-label={`Remove tag ${i + 1}`}
                      onClick={() => setTags(tags.filter((_, n) => n !== i))}
                    >
                      ×
                    </button>
                  </div>
                ))}
                <button onClick={() => setTags([...tags, ['', '']])}>Add tag</button>
                <button
                  disabled={!pendingTags}
                  onClick={() => edit((next) => next.setTags(selected, tags))}
                >
                  Apply tags
                </button>
                <button disabled={!pendingTags} onClick={() => setTagDraft(null)}>
                  Reset tags
                </button>
                {refs.length > 0 && (
                  <>
                    <h4>Boundary / path</h4>
                    <p>
                      Drag blue vertices. Click a green + to insert a vertex; drag it to the desired
                      position. Click a vertex to remove it or mark an entrance.
                    </p>
                    <label>
                      <input
                        type="checkbox"
                        checked={entrances}
                        onChange={(event) => setEntrances(event.target.checked)}
                      />{' '}
                      Insert entrances at midpoint handles
                    </label>
                    {shared && (
                      <>
                        <p>
                          Red vertices are shared and locked. Detaching copies them for this way and
                          disconnects it from neighboring geometry.
                        </p>
                        <button
                          disabled={pendingTags}
                          onClick={() => {
                            if (
                              window.confirm(
                                'Copy shared vertices (including their tags) into this way? This disconnects shared paths/boundaries.',
                              )
                            )
                              edit((next) => next.detach(selected));
                          }}
                        >
                          Detach shared vertices
                        </button>
                      </>
                    )}
                    {vertexKey && (
                      <div className="notice">
                        <p>
                          Vertex {vertex! + 1}: {vertexKey}
                        </p>
                        <button
                          disabled={pendingTags}
                          onClick={() => edit((next) => next.removeVertex(selected, vertex!))}
                        >
                          Remove vertex
                        </button>
                        <button
                          disabled={pendingTags}
                          onClick={() =>
                            edit((next) => {
                              const tags = next.tags(vertexKey).filter(([k]) => k !== 'entrance');
                              next.setTags(vertexKey, [...tags, ['entrance', 'yes']]);
                              return vertexKey;
                            })
                          }
                        >
                          Mark entrance / edit tags
                        </button>
                        <button onClick={() => select(vertexKey)}>Inspect node</button>
                      </div>
                    )}
                  </>
                )}
                {selected.startsWith('node/') && (
                  <p>
                    {model.users(selected).length
                      ? 'This node belongs to another object. Select its way to edit geometry; its tags can be edited here.'
                      : 'Drag the blue handle to move this point.'}
                  </p>
                )}
                {members && members.length > 0 && (
                  <>
                    <h4>Relation members</h4>
                    <p>
                      Select a member way to edit its vertices. Relation membership is preserved.
                    </p>
                    {Array.from(members).map((member, i) => {
                      const key = member.id;
                      return (
                        <button
                          key={i}
                          disabled={!model.objects.has(key)}
                          onClick={() => select(key)}
                        >
                          {member.role || 'member'}: {key}
                        </button>
                      );
                    })}
                  </>
                )}
              </>
            )}
          </fieldset>
        )}
      </aside>
      <div className="canvas" style={{ pointerEvents: busy ? 'none' : 'auto' }}>
        {model && (
          <MapContainer
            center={[43.5853, -84.7732]}
            zoom={16}
            style={{ height: '100%', minHeight: '60vh' }}
            doubleClickZoom={false}
          >
            {tiles && (
              <TileLayer
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              />
            )}
            <Features model={model} selected={selected} select={select} mode={mode} />
            <Focus model={model} selected={selected} />
            <Clicks click={click} />
            {points.length > 0 && (
              <Polyline positions={points} pathOptions={{ color: '#e36914', dashArray: '6 6' }} />
            )}
            {mode === 'select' &&
              !pendingTags &&
              vertices.map((ref, index) => {
                if (!model.objects.has(ref)) return null;
                const locked = model.users(ref).some((key) => key !== selected);
                return (
                  <Marker
                    key={`${draft.length}-${index}-${ref}`}
                    position={model.position(ref)}
                    icon={locked ? sharedIcon : vertexIcon}
                    draggable={!locked}
                    eventHandlers={{
                      click: (event) => {
                        L.DomEvent.stopPropagation(event.originalEvent);
                        setVertex(index);
                      },
                      dragend: (event) => {
                        const p = event.target.getLatLng();
                        edit((next) => next.move(ref, [p.lat, p.lng]));
                      },
                    }}
                  />
                );
              })}
            {mode === 'select' &&
              !pendingTags &&
              refs.slice(0, -1).map((ref, index) => {
                if (!model.objects.has(ref) || !model.objects.has(refs[index + 1])) return null;
                const a = model.position(ref),
                  b = model.position(refs[index + 1]);
                const midpoint: Position = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
                return (
                  <Marker
                    key={`edge-${index}`}
                    position={midpoint}
                    icon={entrances ? entranceIcon : midpointIcon}
                    eventHandlers={{
                      click: (event) => {
                        L.DomEvent.stopPropagation(event.originalEvent);
                        edit((next) => {
                          const node = next.insertVertex(selected, index, midpoint, entrances);
                          return entrances ? node : undefined;
                        });
                      },
                    }}
                  />
                );
              })}
            {mode === 'select' &&
              !pendingTags &&
              selected.startsWith('node/') &&
              validSelection &&
              !model.users(selected).length && (
                <Marker
                  position={model.position(selected)}
                  icon={vertexIcon}
                  draggable
                  eventHandlers={{
                    dragend: (event) => {
                      const p = event.target.getLatLng();
                      edit((next) => next.move(selected, [p.lat, p.lng]));
                    },
                  }}
                />
              )}
          </MapContainer>
        )}
      </div>
    </div>
  );
}
